//! Encrypted local database (SQLCipher, AES-256), one per Google account. Each
//! account has its own folder and its own 256-bit key (generated by the OS and
//! stored only in the system keychain).

use std::path::{Path, PathBuf};
use std::sync::Mutex;

use rusqlite::hooks::{AuthAction, AuthContext, Authorization};
use rusqlite::{named_params, params, Connection, OpenFlags, OptionalExtension};
use serde::Serialize;
use zeroize::Zeroizing;

use crate::error::{AppError, AppResult};
use crate::secrets;

const SCHEMA: &str = include_str!("../sql/schema.sql");
const SCHEMA_VERSION: i64 = 1;
const PROBLEMS_SQL: &str = include_str!("../sql/problems.sql");
const DB_FILE: &str = "stackquake.db";

pub struct Db {
    dir: PathBuf,
    path: PathBuf,
    key_name: String,
    conn: Mutex<Connection>,
}

fn hex(bytes: &[u8]) -> Zeroizing<String> {
    const H: &[u8; 16] = b"0123456789abcdef";
    let mut s = Zeroizing::new(String::with_capacity(bytes.len() * 2));
    for b in bytes {
        s.push(H[(b >> 4) as usize] as char);
        s.push(H[(b & 0xf) as usize] as char);
    }
    s
}

fn now() -> String {
    chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string()
}

/// Folder accessible only by the current user.
pub fn private_dir(dir: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dir)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(dir, std::fs::Permissions::from_mode(0o700))?;
    }
    Ok(())
}

/// Applies the SQLCipher key and checks that it opens the database.
fn unlock(conn: &Connection, key_hex: &str) -> AppResult<()> {
    // key_hex is generated by us (only [0-9a-f]), so it can go into the PRAGMA text.
    debug_assert!(key_hex.bytes().all(|b| b.is_ascii_hexdigit()));
    conn.execute_batch(&Zeroizing::new(format!("PRAGMA key = \"x'{key_hex}'\";")))?;
    conn.query_row("SELECT count(*) FROM sqlite_master", [], |r| {
        r.get::<_, i64>(0)
    })
    .map_err(|_| AppError::known("db_unlock_failed"))?;
    Ok(())
}

/// KPI authorizer: read-only; everything else (writes, ATTACH, PRAGMA, object
/// creation) is denied when the statement is prepared.
fn kpi_authorizer(ctx: AuthContext<'_>) -> Authorization {
    match ctx.action {
        AuthAction::Select
        | AuthAction::Read { .. }
        | AuthAction::Function { .. }
        | AuthAction::Recursive => Authorization::Allow,
        _ => Authorization::Deny,
    }
}

fn remove_db_files(path: &Path) -> std::io::Result<()> {
    for suffix in ["", "-wal", "-shm"] {
        let p = PathBuf::from(format!("{}{suffix}", path.display()));
        if p.exists() {
            std::fs::remove_file(p)?;
        }
    }
    Ok(())
}

fn db_key(path: &Path, key_name: &str) -> AppResult<Zeroizing<String>> {
    if let Some(k) = secrets::get(key_name)? {
        return Ok(k);
    }
    // Without the key the file is unreadable forever: start from scratch.
    remove_db_files(path)?;
    let key = hex(&*secrets::random_bytes::<32>()?);
    secrets::set(key_name, &key)?;
    Ok(key)
}

fn open_rw(path: &Path, key_name: &str) -> AppResult<Connection> {
    let key = db_key(path, key_name)?;
    let conn = Connection::open(path)?;
    unlock(&conn, &key)?;
    conn.query_row("PRAGMA journal_mode = WAL", [], |_| Ok(()))?;
    conn.execute_batch("PRAGMA foreign_keys = ON; PRAGMA secure_delete = ON;")?;
    let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
    if version < SCHEMA_VERSION {
        conn.execute_batch(SCHEMA)?;
        conn.execute_batch(&format!("PRAGMA user_version = {SCHEMA_VERSION}"))?;
    }
    Ok(conn)
}

